import React, { useState } from 'react';

function AdminLoginModal({ adminToken, setAdminToken }) {
  const [tokenInput, setTokenInput] = useState('');

  const login = () => {
    setAdminToken(tokenInput);
    localStorage.setItem('adminToken', tokenInput);
    setTokenInput('');
  };

  const logout = () => {
    setAdminToken('');
    localStorage.removeItem('adminToken');
  };

  return (
    <div className="modal fade" id="adminLoginModal" tabIndex="-1" aria-hidden="true">
      <div className="modal-dialog">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title">تسجيل دخول الأدمن</h5>
            <button type="button" className="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
          </div>
          <div className="modal-body">
            {adminToken ? (
              <div>
                <p>مرحبًا، أنت متصل كأدمن.</p>
                <button className="btn btn-danger" onClick={logout} data-bs-dismiss="modal">تسجيل الخروج</button>
              </div>
            ) : (
              <div>
                <label className="form-label">أدخل رمز الأدمن</label>
                <input className="form-control" value={tokenInput} onChange={e => setTokenInput(e.target.value)} />
                <div className="mt-3 d-flex justify-content-end">
                  <button className="btn btn-secondary me-2" data-bs-dismiss="modal">إغلاق</button>
                  <button className="btn btn-primary" onClick={() => { login(); document.querySelectorAll('[data-bs-dismiss="modal"]').forEach(b=>b.click()); }}>دخول</button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default AdminLoginModal;
